#!/usr/bin/env python3
"""Minimal lnav stub reimplementation — observes CLI behavior only.

This is NOT a full implementation of lnav; it handles the subset of
command-line interactions that can be observed from the compiled binary.
"""

from __future__ import annotations

import os
import sys
from pathlib import Path

VERSION = "lnav 0.14.0-07efb63"

# Exit codes used by the original binary
EXIT_OK = 0
EXIT_NOTHING_TO_DO = 1
EXIT_OPEN_FAIL = 1
EXIT_TTY_REQUIRED = 1
EXIT_UNEXPECTED_ARG = 109
EXIT_MISSING_VALUE = 114
EXIT_INVALID_VALUE = 105

HERE = Path(__file__).resolve().parent


def _data_path(name: str) -> Path:
    return HERE / "data" / name


def _load_data(name: str) -> str:
    return _data_path(name).read_text(encoding="utf-8")


def emit_error(lines: list[str], *, file=sys.stderr) -> None:
    for line in lines:
        print(line, file=file)


def error_invalid_args(reason: str) -> None:
    emit_error(
        [
            "  error: invalid command-line arguments",
            f" reason: {reason}",
        ]
    )


def error_tty() -> None:
    emit_error(
        [
            "  error: unable to display interactive text UI",
            " reason: stdout is not a TTY",
            " = help: pass the -n option to run lnav in headless mode or "
            "don't redirect stdout",
        ]
    )


def error_nothing_to_do() -> None:
    emit_error(
        [
            "  error: nothing to do",
            " reason: no files given or default files found",
            " = help: use the \u201c-N\u201d option to open lnav without "
            "loading any files",
        ]
    )


def resolved_binary() -> str:
    argv0 = sys.argv[0] if sys.argv else ""
    if not argv0:
        return ""
    try:
        return str(Path(argv0).resolve())
    except OSError:
        return os.path.realpath(argv0)


def config_dir() -> str:
    home = os.environ.get("HOME", "")
    if home and Path(home).is_dir():
        return str(Path(home) / ".lnav")
    return os.getcwd()


def work_dir() -> str:
    tmp = os.environ.get("TMPDIR") or "/tmp"
    return f"{tmp.rstrip('/') or '/'}/lnav-user-{os.getuid()}-work"


def render_help(argv0: str) -> str:
    template = _load_data("help_template.txt")
    return template.format(
        ARGV0=argv0,
        BINARY=resolved_binary(),
        CONFIG=config_dir(),
        WORK=work_dir(),
    )


# ----------------------------------------------------------------------------
# argument parsing
# ----------------------------------------------------------------------------


SHORT_FLAGS = set("hHWurRtnNqVm")
SHORT_WITH_VALUE = {
    "-I": "TEXT:DIR",
    "-d": "FILE",
    "-c": "",
    "-f": "",
    "-e": "",
    "-S": "TEXT",
    "-U": "TEXT",
    "-i": "file",
}
LONG_ALIASES = {
    "--since": "-S",
    "--until": "-U",
    "--help": "-h",
    "--version": "-V",
}


class ParsedArgs:
    def __init__(self) -> None:
        self.flags: dict[str, bool] = {}
        self.values: dict[str, list[str]] = {}
        self.positional: list[str] = []

    def has(self, flag: str) -> bool:
        return self.flags.get(flag, False)


class ArgError(Exception):
    def __init__(self, message: str, exit_code: int = EXIT_UNEXPECTED_ARG):
        super().__init__(message)
        self.message = message
        self.exit_code = exit_code


def parse_args(argv: list[str]) -> ParsedArgs:
    parsed = ParsedArgs()
    unexpected: list[str] = []

    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
            parsed.positional.extend(argv[i + 1 :])
            break

        # Long option handling (only -h/-V/--since/--until)
        if arg.startswith("--"):
            canonical = LONG_ALIASES.get(arg)
            if canonical is None:
                # Long options with =value?  Just treat as unexpected.
                unexpected.append(arg)
                i += 1
                continue
            arg = canonical

        if arg.startswith("-") and len(arg) > 1:
            # A bundle like "-nV" or "-hV" — split into individual short flags
            # unless the first letter requires a value.
            letters = arg[1:]
            if letters[0:1] in {c for c in "".join(SHORT_WITH_VALUE)}:
                # option with value: -Ivalue or -I value
                short = "-" + letters[0]
                if short in SHORT_WITH_VALUE:
                    if len(letters) > 1:
                        value = letters[1:]
                    else:
                        if i + 1 >= len(argv):
                            label = SHORT_WITH_VALUE[short]
                            if label:
                                raise ArgError(
                                    f"{short}: 1 required {label} missing",
                                    EXIT_MISSING_VALUE,
                                )
                            raise ArgError(
                                f"{short}: 1 required  missing",
                                EXIT_MISSING_VALUE,
                            )
                        i += 1
                        value = argv[i]
                    parsed.values.setdefault(short, []).append(value)
                    i += 1
                    continue
            # plain bundle of flags
            ok = True
            for ch in letters:
                if ch in SHORT_FLAGS:
                    parsed.flags["-" + ch] = True
                else:
                    ok = False
                    break
            if ok:
                i += 1
                continue
            unexpected.append(arg)
            i += 1
            continue

        # positional
        parsed.positional.append(arg)
        i += 1

    if unexpected:
        if len(unexpected) == 1:
            raise ArgError(
                f"The following argument was not expected: {unexpected[0]}",
                EXIT_UNEXPECTED_ARG,
            )
        raise ArgError(
            "The following arguments were not expected: "
            + " ".join(reversed(unexpected)),
            EXIT_UNEXPECTED_ARG,
        )

    return parsed


# ----------------------------------------------------------------------------
# runtime actions
# ----------------------------------------------------------------------------


def validate_option_values(parsed: ParsedArgs) -> None:
    """Check semantic validity of option values (paths, command prefixes)."""
    for value in parsed.values.get("-I", []):
        if not Path(value).is_dir():
            raise ArgError(
                f"-I: Directory does not exist: {value}",
                EXIT_INVALID_VALUE,
            )
    for option in ("-c",):
        for value in parsed.values.get(option, []):
            if not value or value[0] not in {":", ";", "|"}:
                msg = (
                    f"  error: invalid value for \u201c{option}\u201d option\n"
                    f" --> command-line argument\n"
                    f" |  {option} {value:38}\n"
                    f" |     ^ command type prefix is missing    \n"
