                sys.stderr.write(msg + "\n")
                raise ArgError("", EXIT_INVALID_VALUE)


def run_headless(parsed: ParsedArgs) -> int:
    files = parsed.positional
    stdin_piped = not sys.stdin.isatty()

    # Read stdin if something is piped in and no files were given (and -N not set)
    if not files and not stdin_piped and not parsed.has("-N"):
        error_nothing_to_do()
        return EXIT_NOTHING_TO_DO

    quiet = parsed.has("-q")

    # Open files first so we can error before emitting anything
    open_files = []
    for name in files:
        try:
            fh = open(name, "rb")
        except FileNotFoundError:
            emit_error(
                [
                    f"  error: unable to open file: {name}",
                    " reason: No such file or directory",
                ]
            )
            return EXIT_OPEN_FAIL
        except IsADirectoryError:
            emit_error(
                [
                    f"  error: unable to open file: {name}",
                    " reason: Is a directory",
                ]
            )
            return EXIT_OPEN_FAIL
        except PermissionError:
            emit_error(
                [
                    f"  error: unable to open file: {name}",
                    " reason: Permission denied",
                ]
            )
            return EXIT_OPEN_FAIL
        open_files.append(fh)

    if quiet:
        for fh in open_files:
            fh.close()
        return EXIT_OK

    out = sys.stdout.buffer
    for fh in open_files:
        try:
            while True:
                buf = fh.read(65536)
                if not buf:
                    break
                out.write(buf)
        finally:
            fh.close()

    if not files and stdin_piped and not parsed.has("-N"):
        # Cat stdin
        if parsed.has("-t"):
            # prepend timestamps — best-effort
            import datetime

            for line in sys.stdin.buffer:
                now = datetime.datetime.now(datetime.timezone.utc)
                stamp = now.strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3] + "+0000"
                out.write(stamp.encode() + b" ")
                out.write(line)
        else:
            while True:
                buf = sys.stdin.buffer.read(65536)
                if not buf:
                    break
                out.write(buf)

    out.flush()
    return EXIT_OK


def run_update_formats() -> int:
    print(
        "No formats from git repositories found, use 'lnav -i extra' to "
        "install third-party formats"
    )
    return EXIT_OK


def main(argv: list[str] | None = None) -> int:
    argv0 = sys.argv[0] if sys.argv else "lnav"
    args = sys.argv[1:] if argv is None else argv

    try:
        parsed = parse_args(args)
    except ArgError as err:
        error_invalid_args(err.message)
        return err.exit_code

    # -V short-circuit
    if parsed.has("-V"):
        print(VERSION)
        return EXIT_OK

    # -h short-circuit
    if parsed.has("-h"):
        sys.stderr.write(render_help(argv0))
        return EXIT_OK

    # Semantic validation (after short-circuits)
    try:
        validate_option_values(parsed)
    except ArgError as err:
        if err.message:
            error_invalid_args(err.message)
        return err.exit_code

    if parsed.has("-u"):
        return run_update_formats()

    # -H handling
    if parsed.has("-H"):
        if not parsed.has("-n") and not sys.stdout.isatty():
            error_tty()
            return EXIT_TTY_REQUIRED
        sys.stdout.write(_load_data("internal_help.txt"))
        return EXIT_OK

    # Default: if -n not set and stdout is not a TTY, error out
    if not parsed.has("-n") and not sys.stdout.isatty():
        # Try to open files anyway for parity with original behavior
        had_file_err = False
        for name in parsed.positional:
            if not Path(name).exists():
                emit_error(
                    [
                        f"  error: unable to open file: {name}",
                        " reason: No such file or directory",
                    ]
                )
                had_file_err = True
        error_tty()
        return EXIT_TTY_REQUIRED

    if parsed.has("-n"):
        return run_headless(parsed)

    # TUI mode is not implemented — mimic "cannot display" when possible.
    error_tty()
    return EXIT_TTY_REQUIRED


if __name__ == "__main__":
    try:
        sys.exit(main())
    except BrokenPipeError:
        sys.exit(0)
